/* eslint-disable max-lines, max-lines-per-function */
/**
 * Per-block output field schemas for Frink Flows.
 *
 * These schemas describe what each block type puts in `node_runs.node_output.outputs`
 * when it completes. They are used by:
 * - The flow editor "Available Variables" UI panel (renderer)
 * - The `frink-flows` Claude skill (references generated by
 *   `scripts/build-skill-content.ts` and shipped to `~/.frink/skills/frink-flows/`)
 *
 * **Authoritative runtime shapes** — what handlers actually write into `outputs` — live in
 * `src/main/lib/flows/dispatch/`. Update those handlers and this file together.
 */
/**
 * Declares one output field produced by a custom node.
 * Defined here (shared) so both the Electron main process (discovery, cloud DTO)
 * and the renderer (AvailableVariables hook) can import the same type.
 */
export type ManifestOutputField = {
  type: 'string' | 'number' | 'boolean' | 'object' | 'array';
  description?: string;
  /** Sub-fields for array-of-objects. Omit for arrays of primitives. */
  items?: Record<string, ManifestOutputField>;
};
/**
 * Declares what JSON fields a `run_command` node will output to stdout.
 * Stored in the node's `config.expectedOutputs`. Same shape as custom node manifest outputs.
 *
 * When declared, these fields appear as chips in the Available Variables panel and are
 * validated by the template variable checker. `exitCode` is always present in addition.
 *
 * Example config:
 * ```json
 * {
 *   "timestamp": { "type": "string", "description": "ISO timestamp of execution" },
 *   "message": { "type": "string", "description": "Status message" }
 * }
 * ```
 */
export type RunCommandExpectedOutputs = Record<string, ManifestOutputField>;
export type OutputFieldSchema = {
  key: string;
  /** JSON-level type of the value */
  type: 'string' | 'number' | 'boolean' | 'object' | 'array' | 'unknown';
  description: string;
  /** True if this field is always present; false if it only appears in some cases */
  guaranteed: boolean;
};
export type TriggerFieldSchema = {
  key: string;
  type: 'string' | 'number' | 'boolean' | 'object' | 'array' | 'unknown';
  description: string;
  /** Which trigger types produce this field (omit to mean "all triggers") */
  triggers?: string[];
  /**
   * True for an open-ended object whose sub-fields can't be validated at design
   * time (e.g. `payload` = the raw provider webhook body). The editor renders
   * `{{trigger.<key>.*}}` deep paths as "dynamic" (resolves at runtime) rather
   * than confident-valid, since field names are provider-specific.
   */
  openEnded?: boolean;
};
/**
 * Output fields each block type writes to `outputs` when it completes.
 * Accessible in templates as `{{previous.<key>}}`.
 *
 * Notes:
 * - `run_command` / custom nodes: if stdout is valid JSON, its fields are spread
 *   into outputs alongside `exitCode`. If not JSON, `_rawStdout` is populated instead.
 * - `condition`: passes through all upstream `outputs` fields plus `result`.
 * - `fan_out`: the body node sees a synthetic `outputs` with `currentItem` etc.
 *   The node after fan_out sees aggregated `results`.
 * - `approval`: no outputs (flow is paused, not completed).
 * - Trigger blocks: no previous outputs (use `{{trigger.*}}` instead).
 */
