/**
 * Trigger types where triggerContext keys are user-supplied and open-ended.
 * `checkTriggerPath` skips unknown-field warnings for these types.
 *
 * `manual_trigger` accepts arbitrary user-defined keys via `define_stages` /
 * `frink_flows_run` `triggerContext` (e.g. ticketId, workstreamId, storyId).
 * The `buildFlowTemplateVariables` runtime spreads the full `flowTriggerContext`
 * onto `trigger.*` with no filtering, so any key is valid at runtime.
 */
export const TRIGGER_ALLOWS_ARBITRARY_KEYS: ReadonlySet<string> = new Set(['manual_trigger']);

/**
 * Fallback output schema for custom nodes that don't declare their outputs in manifest.json.
 * Follows the same shape as run_command: exitCode + optional _rawStdout when stdout isn't JSON.
 * When a custom node declares `outputs` in its manifest, those fields are used instead.
 */
export const CUSTOM_NODE_FALLBACK_OUTPUT_SCHEMA: OutputFieldSchema[] = OUTPUT_SCHEMAS.run_command;

/** Converts manifest-declared output fields into `OutputFieldSchema[]` — shared by the
 * renderer and `frink_flows_patch` so both resolve a manifest's outputs identically. */
export function manifestOutputsToSchema(
  outputs: Record<string, ManifestOutputField> | undefined,
): OutputFieldSchema[] {
  if (!outputs) return [];
  return Object.entries(outputs).map(([key, field]) => ({
    key,
    type: field.type as OutputFieldSchema['type'],
    description: field.description ?? key,
    guaranteed: true,
  }));
}

/** Converts `expectedOutputs` into `OutputFieldSchema[]`, prepending the always-present
 * `exitCode` unless the caller already declared one. */
export function resolveRunCommandOutputSchema(
  expectedOutputs: RunCommandExpectedOutputs,
): OutputFieldSchema[] {
  const exitCodeField = OUTPUT_SCHEMAS.run_command?.find((f) => f.key === 'exitCode');
  const declared = manifestOutputsToSchema(expectedOutputs);
  if (exitCodeField && !declared.some((f) => f.key === 'exitCode')) {
    return [exitCodeField, ...declared];
  }
  return declared;
}

/** Scalar `{{loop.*}}` fields for every node inside a fan_out body chain (per-item
 * fields like `{{loop.currentItem.*}}` are resolved separately). */
export const LOOP_CONTEXT_SCHEMA: OutputFieldSchema[] = [
  {
    key: 'currentIndex',
    type: 'number',
    description: 'Zero-based index of the current iteration (0 = first item)',
    guaranteed: true,
  },
  {
    key: 'totalCount',
    type: 'number',
    description: 'Total number of items being iterated',
    guaranteed: true,
  },
];
